<template><view class="page"><nav-bar title="我的题库组" :showBack="true" placeholder/><view class="toolbar"><input v-model="keyword" placeholder="搜索题库组" @confirm="load"/><button @click="edit()">新建</button></view><view v-if="loading" class="state">加载中...</view><view v-else-if="!banks.length" class="state">暂无题库组</view><view v-for="bank in banks" :key="bank.id" class="card"><view @click="detail(bank.id)"><text class="name">{{bank.name}}</text><text class="meta">{{subjectName(bank.subjectId)}} · {{bank.bankType||'自定义'}}</text><text class="meta">{{bank.questionCount||0}} 道题 · {{permissionText(bank.visibility)}}</text><text class="meta">更新：{{bank.updateTime||'-'}}</text></view><view class="actions"><text @click="edit(bank.id)">编辑</text><text class="danger" @click="remove(bank)">删除</text></view></view></view></template>
<script>import NavBar from '@/components/nav-bar/nav-bar.vue';import{listPaperBanks,deletePaperBank,listPaperDictionaries}from'@/api/paper.js';export default{components:{NavBar},data(){return{banks:[],subjects:[],keyword:'',loading:false}},onShow(){this.load()},methods:{async load(){this.loading=true;try{const[bankResult,subjectResult]=await Promise.all([listPaperBanks({visibility:'private',keyword:this.keyword}),listPaperDictionaries('subject')]);this.banks=bankResult.data||[];this.subjects=subjectResult.data||[]}finally{this.loading=false}},subjectName(id){const item=this.subjects.find(subject=>Number(subject.dictCode)===Number(id));return item?item.name:'未设置科目'},permissionText(v){return v==='shared'?'题库成员可见':'仅自己可见'},edit(id){uni.navigateTo({url:`/subpackage_ai/paperBankEdit/paperBankEdit${id?'?id='+id:''}`})},detail(id){uni.navigateTo({url:`/subpackage_ai/paperBankDetail/paperBankDetail?id=${id}`})},remove(bank){uni.showModal({title:'确认删除？',content:'删除后题库组无法恢复。',confirmText:'删除',confirmColor:'#df6565',success:async r=>{if(r.confirm){await deletePaperBank(bank.id);this.banks=this.banks.filter(x=>x.id!==bank.id);uni.showToast({title:'删除成功'})}}})}}}</script>
<style scoped>.page{min-height:100vh;background:#f5f8fc;padding:24rpx}.toolbar{display:flex;gap:14rpx;margin-bottom:20rpx}.toolbar input{flex:1;background:#fff;border-radius:28rpx;padding:15rpx 22rpx}.toolbar button{background:#4d78e8;color:#fff;border-radius:28rpx;font-size:24rpx}.card{background:#fff;border-radius:18rpx;padding:24rpx;margin-bottom:16rpx}.name{display:block;font-size:30rpx;font-weight:700}.meta{display:block;color:#8c98aa;font-size:23rpx;margin-top:10rpx}.actions{text-align:right;border-top:1rpx solid #edf0f5;margin-top:18rpx;padding-top:15rpx}.actions text{color:#4d78e8;margin-left:28rpx}.actions .danger{color:#df6565}.state{text-align:center;color:#9ca7b6;padding:120rpx}</style>
